with with_prev as (select *, lag(started_at) over (partition by device order by started_at, id) as prev_started_at from sessions), gaps as (select *, case when prev_started_at is null or started_at > prev_started_at + interval '90' day then 1 else 0 end as session_start_flag from with_prev) select id, device, started_at, country, sum(session_start_flag) over (partition by device order by started_at, id rows between unbounded preceding and current row) as burst_id from gaps
